#include <iostream>
using namespace std;

int main() {
    int x = 7;
    int y = 2;

    double wrongValue = x / y;
    double correctValue = static_cast<double>(x) / y;

    cout << wrongValue << '\n';
    cout << correctValue << '\n';
    return 0;
}

#include <iostream>
#include <cctype>
using namespace std;

int main() {
    char character = 'g';
    char digit = '8';

    cout << static_cast<int>(character) << '\n';
    cout << character - 'a' << '\n';
    cout << static_cast<char>(character - 'a' + 'A') << '\n';
    cout << digit - '0' << '\n';
    cout << (isdigit(digit) ? "YES" : "NO") << '\n';
    cout << static_cast<char>(toupper(character)) << '\n';

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    int cnt[26] = {};

    for (char c : s) {
        ++cnt[c - 'a'];
    }

    for (int i = 0; i < 26; ++i) {
        if (cnt[i] > 0) {
            cout << static_cast<char>('a' + i) << ' ' << cnt[i] << '\n';
        }
    }

    return 0;
}

#include <iostream>
#include <cctype>
#include <string>
using namespace std;

int main() {
    string s;
    getline(cin, s);

    for (char &c : s) {
        c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
    }

    cout << s << '\n';
    return 0;
}
